import numpy as np

def swap_rgb_to_bgr(image_rgb: np.ndarray) -> np.ndarray:
    # Membalik urutan saluran warna (index 2, 1, 0) menggunakan slicing [..., ::-1]
    return image_rgb[:, :, ::-1].copy()

import numpy as np

def adjust_contrast_brightness(image_uint8: np.ndarray, alpha: float = 1.2, beta: float = 30.0) -> np.ndarray:
    img_float = image_uint8.astype(np.float32)
    adjusted = alpha * img_float + beta
    clipped = np.clip(adjusted, 0.0, 255.0)
    return clipped.astype(np.uint8)
